	@ParameterizedTest(name = "{0}")
	@MethodSource("nativeCases")
	void semanticNativeOptionalShapesMatchTheGenericBag(Scenario scenario) {
		List<String> generic = rows(scenario.query(), false, null, scenario.projection());
		assertThat(generic).as("generic control for %s", scenario.name()).hasSize(scenario.expectedRows());
		scenario.unboundRows()
				.forEach((name, expected) -> assertThat(unboundRows(generic, name))
						.as("generic %s rows with unbound ?%s", scenario.name(), name)
						.isEqualTo(expected));

		assertSemanticNativeRoute(scenario.query(), scenario.requiredExplainDetails().toArray(String[]::new));
		List<String> actual = rows(scenario.query(), true, "nestedLoop", scenario.projection());
		assertThat(actual).as("full projected bag for %s", scenario.name())
				.containsExactlyInAnyOrderElementsOf(generic);
	}

	@Test
	void lateralOptionalWithUnprovenOccurrenceScopeUsesNamedGenericFallback() {
		String query = PREFIX + "SELECT ?s ?token WHERE { VALUES ?s { ex:a ex:a } "
				+ "LATERAL { OPTIONAL { SELECT ?s ?token WHERE { ?s ex:arg ?arg . "
				+ "BIND(ex:fresh(?arg) AS ?token) } } } }";
		List<String> projection = List.of("s", "token");

		fresh.calls.set(0);
		List<String> generic = rows(query, false, null, projection);
		String subject = NTriplesUtil.toNTriplesString(SimpleValueFactory.getInstance().createIRI(EX, "a"));
		assertThat(generic).containsExactlyInAnyOrder(
				"s=" + subject + "|token=\"fresh/1\"",
				"s=" + subject + "|token=\"fresh/2\"");
		assertThat(fresh.calls).as("generic LATERAL evaluates each duplicate occurrence").hasValue(2);

		assertGenericScopeFallback(query);
		fresh.calls.set(0); // Telemetry explanation itself evaluates the query.
		List<String> actual = rows(query, true, "nestedLoop", projection);
		assertThat(actual).containsExactlyInAnyOrderElementsOf(generic);
		assertThat(fresh.calls).as("the documented fallback preserves per-occurrence function calls").hasValue(2);
	}

