	private void assertSemanticNativeRoute(String query, String... requiredDetails) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, "true");
		long hostedBefore = LmdbNativeAggregateCompiler.HOSTED_GENERIC.get();
		long islandsBefore = LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = nativeQuery(connection, query).explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
			List<String> paths = new ArrayList<>();
			collectPaths(plan, paths);
			assertThat(paths).as("actual semantic-native path: %s", plan)
					.contains("nestedLoop")
					.noneMatch(path -> path.startsWith("genericFallback"));
			assertThat(plan.toString()).contains("NativeRows");
			if (!requiredDetailsIsEmpty(requiredDetails)) {
				assertThat(plan.toString()).contains(requiredDetails);
			}
		} finally {
			restore(NATIVE_FLAG, previous);
		}
		assertThat(LmdbNativeAggregateCompiler.HOSTED_GENERIC.get()).isEqualTo(hostedBefore);
		assertThat(LmdbNativeAggregateCompiler.ISLANDS_COMPILED.get()).isEqualTo(islandsBefore);
	}

	private void assertGenericScopeFallback(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, "true");
		try (SailRepositoryConnection connection = repository.getConnection()) {
			GenericPlanNode plan = nativeQuery(connection, query).explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
			List<String> paths = new ArrayList<>();
			collectPaths(plan, paths);
			assertThat(plan.toString()).contains("genericHostedRoot", "optional-scope-unproven");
			assertThat(paths).as("unproven LATERAL occurrence scope stays on the named generic fallback")
					.noneMatch(path -> path.contains("nestedLoop"));
		} finally {
			restore(NATIVE_FLAG, previous);
		}
	}

	private List<String> rows(String query, boolean nativeExecution, String forcedStrategy, List<String> projection) {
		String previous = System.getProperty(NATIVE_FLAG);
		System.setProperty(NATIVE_FLAG, Boolean.toString(nativeExecution));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			if (forcedStrategy != null) {
				prepared.setForcedLmdbExecutionStrategy(forcedStrategy);
			}
			return QueryResults.asList(prepared.evaluate())
					.stream()
					.map(bindings -> canonical(bindings, projection))
					.toList();
		} finally {
			restore(NATIVE_FLAG, previous);
		}
	}

	private static String canonical(BindingSet bindings, List<String> projection) {
		return projection.stream()
				.map(name -> name + "=" + (bindings.hasBinding(name)
						? NTriplesUtil.toNTriplesString(bindings.getValue(name))
						: "<UNBOUND>"))
				.reduce((left, right) -> left + "|" + right)
				.orElse("");
	}

	private static long unboundRows(List<String> rows, String variable) {
		return rows.stream().filter(row -> row.contains(variable + "=<UNBOUND>")).count();
	}

	private static SailTupleQuery nativeQuery(SailRepositoryConnection connection, String query) {
		SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
		prepared.setForcedLmdbExecutionStrategy("nestedLoop");
		return prepared;
	}

	private static void collectPaths(GenericPlanNode node, List<String> paths) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			for (String part : path.split("\\|")) {
				paths.add(part.trim());
			}
		}
		if (node.getPlans() != null) {
			node.getPlans().forEach(child -> collectPaths(child, paths));
		}
	}

	private static boolean requiredDetailsIsEmpty(String[] requiredDetails) {
		return requiredDetails == null || requiredDetails.length == 0;
	}

	private static void restore(String property, String value) {
		if (value == null) {
			System.clearProperty(property);
		} else {
			System.setProperty(property, value);
		}
	}

	private record Scenario(String name, String query, List<String> projection, int expectedRows,
			Map<String, Long> unboundRows, List<String> requiredExplainDetails) {
	}

	private static final class FreshFunction implements Function {
		private final AtomicInteger calls = new AtomicInteger();

		@Override
		public String getURI() {
			return FRESH_URI;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... arguments) throws ValueExprEvaluationException {
			if (arguments.length != 1) {
				throw new ValueExprEvaluationException("Expected one store-bound argument");
			}
			return valueFactory.createLiteral("fresh/" + calls.incrementAndGet());
		}
	}
